def _backfill() -> None:
    """Fill the new columns for existing data."""
    import json
    import secrets

    conn = op.get_bind()
    # Spins made before items existed: the original list is the current list.
    conn.execute(sa.text("UPDATE spinassignment SET original_options = options"))
    # Every run gets a lobby code (used by the online lobby later).
    for (run_id,) in conn.execute(sa.text("SELECT id FROM run WHERE lobby_code IS NULL")).fetchall():
        conn.execute(sa.text("UPDATE run SET lobby_code = :c WHERE id = :i"), {"c": secrets.token_hex(3).upper(), "i": run_id})
    # Match fields that were not imported before (multikills, healing, role), read from the cached raw JSON.
    rows = conn.execute(
        sa.text(
            "SELECT s.match_id, s.player_id, p.puuid, m.raw_json FROM playermatchstats s "
            "JOIN player p ON p.id = s.player_id JOIN riotmatch m ON m.match_id = s.match_id"
        )
    ).fetchall()
    for match_id, player_id, puuid, raw in rows:
        data = json.loads(raw) if isinstance(raw, str) else raw
        part = next((x for x in data.get("info", {}).get("participants", []) if x.get("puuid") == puuid), None)
        if not part:
            continue
        conn.execute(
            sa.text(
                "UPDATE playermatchstats SET team_position = :tp, double_kills = :d, triple_kills = :t, "
                "quadra_kills = :q, penta_kills = :pk, heals_on_teammates = :h, shields_on_teammates = :sh "
                "WHERE match_id = :m AND player_id = :p"
            ),
            {
                "tp": part.get("teamPosition") or "",
                "d": part.get("doubleKills", 0),
                "t": part.get("tripleKills", 0),
                "q": part.get("quadraKills", 0),
                "pk": part.get("pentaKills", 0),
                "h": part.get("totalHealsOnTeammates", 0),
                "sh": part.get("totalDamageShieldedOnTeammates", 0),
                "m": match_id,
                "p": player_id,
            },
        )


